<?php
// Usage: php snapshot.php save|restore  (state kept in /tmp/inspect/state.json)
$pdo = new PDO("pgsql:host=postgres;port=5432;dbname=llmapi_eval", "eval_rw", "eval_rw", [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$file = '/tmp/inspect/state.json';
if ($argv[1] === 'save') {
    $state = [
        'book' => $pdo->query('SELECT * FROM book ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),
        'purchase_max' => (int) $pdo->query('SELECT COALESCE(MAX(id),0) FROM purchase')->fetchColumn(),
        'purchase_line_max' => (int) $pdo->query('SELECT COALESCE(MAX(id),0) FROM purchase_line')->fetchColumn(),
    ];
    file_put_contents($file, json_encode($state, JSON_PRETTY_PRINT));
    echo "saved\n";
} else {
    $state = json_decode(file_get_contents($file), true);
    $pdo->beginTransaction();
    $pdo->exec('DELETE FROM purchase_line WHERE id > ' . $state['purchase_line_max']);
    $pdo->exec('DELETE FROM purchase WHERE id > ' . $state['purchase_max']);
    foreach ($state['book'] as $b) {
        $st = $pdo->prepare('UPDATE book SET title=?, author_id=?, published=?, price_cents=?, published_at=?, stock=? WHERE id=?');
        $st->execute([$b['title'], $b['author_id'], $b['published'] ? 'true' : 'false', $b['price_cents'], $b['published_at'], $b['stock'], $b['id']]);
    }
    $pdo->commit();
    echo "restored\n";
}
